            //
            aOrbiterA = ((aOrbiterA + aOrbiterE) + 0x20FD0EC784BC4F49ULL) + aOrbiterUpdateSaltB[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterA) ^ 0x4C8CA264D8BD0EF5ULL) ^ aNonceWordH;
            aOrbiterJ = RotL64((aOrbiterJ * 0xD4F69AE8A17488ABULL), 13U);
