            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x1B4DE63D237E8CE6ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterB) ^ 0x1ACD20EE9190D1ACULL) ^ aOrbiterUpdateSaltE[(((31U - aIndex) + 4U)) & S_SALT1];
