            aOrbiterG = ((aOrbiterG + aOrbiterH) + 0x3B6282214EF07E41ULL) + aOrbiterUpdateSaltD[((aIndex + 17U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0x794EA1BB22210BA5ULL;
