            aOrbiterK = (aWandererK + RotL64(aIngress, 3U)) + 0x1316D0582A0B2BCCULL;
            aOrbiterH = ((aWandererF + RotL64(aCross, 19U)) + RotL64(aCarry, 47U)) + 0x8E74164F68BCAA91ULL;
