            aOrbiterD = ((aWandererH + RotL64(aIngress, 51U)) + 0xB18980E5D62AA654ULL) + aPhaseAOrbiterAssignSaltD[((aIndex + 29U)) & S_SALT1];
            aOrbiterC = (aWandererC + RotL64(aPrevious, 24U)) + 0x6D29239223B7C1D3ULL;
            aOrbiterF = (aWandererB + RotL64(aScatter, 5U)) + 0x0F2255F278F15ACAULL;
