            aOrbiterB = (aOrbiterB + aOrbiterK) + 0xFBE9484EF9F8D7BAULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterB) ^ 0xB0580A28E8D6C942ULL) ^ aNonceWordO;
