            aWandererA = aWandererA ^ (((RotL64(aCross, 47U) + aOrbiterK) + RotL64(aOrbiterE, 3U)) + aPhaseCWandererUpdateSaltE[(((31U - aIndex) + 27U)) & S_SALT1]);
            aWandererF = aWandererF + ((RotL64(aScatter, 13U) + RotL64(aOrbiterH, 29U)) + aOrbiterC);
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 23U) + aOrbiterI) + RotL64(aOrbiterA, 48U));
