            aOrbiterE = (((aWandererK + RotL64(aCross, 47U)) + RotL64(aCarry, 11U)) + 0x397AE672FA75579CULL) + aPhaseDOrbiterAssignSaltB[(((31U - aIndex) + 21U)) & S_SALT1];
