            //
            aIngress = (RotL64(aWoodLaneA[((aIndex + 9878U)) & S_BLOCK1], 4U) ^ RotL64(aFireLaneC[((aIndex + 9287U)) & S_BLOCK1], 53U));
            aIngress ^= RotL64(aSource[((aIndex + 8301U)) & S_BLOCK1], 37U);
            aIngress = TwistMix64::DiffuseC(aIngress);
