            aCross = (RotL64(aFireLaneA[((S_BLOCK1 - aIndex + 10429U)) & S_BLOCK1], 21U) ^ RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 10418U)) & S_BLOCK1], 5U));
            aCross ^= RotL64(aPoisonLaneC[((aIndex + 7727U)) & S_BLOCK1], 48U);
