            aOrbiterJ = (aWandererI + RotL64(aIngress, 37U)) + 0x58E573A5F2FED8F6ULL;
            aOrbiterG = (((aWandererE + RotL64(aScatter, 11U)) + RotL64(aCarry, 5U)) + 0xB0BC5A1ADC7C46E6ULL) + aPhaseAOrbiterAssignSaltF[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterD = (aWandererD + RotL64(aCross, 46U)) + 0x79B570B6F7ED6FDEULL;
            aOrbiterH = (((aWandererA + RotL64(aPrevious, 27U)) + RotL64(aCarry, 21U)) + 0xC306FDCA07616B64ULL) + aPhaseAOrbiterAssignSaltE[((aIndex + 11U)) & S_SALT1];
            aOrbiterA = ((aWandererB + RotL64(aIngress, 21U)) + RotL64(aCarry, 57U)) + 0x0A1D0B0B0C7BB428ULL;
            aOrbiterK = (aWandererK + RotL64(aCross, 57U)) + 0xFEA34B744726AF20ULL;
            aOrbiterF = (aWandererF + RotL64(aPrevious, 5U)) + 0x4BD525DEB8F31389ULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterG) + 0x2CACA82D04265503ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterJ) ^ 0x4F9F56105B2E4104ULL) ^ aPhaseAOrbiterUpdateSaltE[((aIndex + 29U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xD670EB92D85B6187ULL), 35U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterD) + 0xBBD78AF101CAD236ULL) + aPhaseAOrbiterUpdateSaltA[((aIndex + 28U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0xDD1C20EF5F0B0BD8ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x85481AE8DF443D65ULL), 21U);
