            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x24B7D4494B825587ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterD) ^ 0x86AF271366277853ULL) ^ aPhaseAOrbiterUpdateSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x0A8AF5F350BAA6BDULL), 41U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterA) + 0x2245086127085AD6ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterF) ^ 0xD693D4148A7EEAD0ULL) ^ aPhaseAOrbiterUpdateSaltD[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xB5C76D7055D6461FULL), 13U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x291636653C09C308ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x33E908AD4B21D259ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xB5DF303DD694FB73ULL), 51U);
            //
            aIngress = RotL64(aOrbiterH, 35U) ^ aOrbiterJ;
            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterG, 21U));
